static const Element* get_elm_xy(uint8_t c, uint8_t r) {
    for(uint16_t i = 0; i < 119; i++)
        if(DB[i].col == c && DB[i].row == r) return &DB[i];
    return NULL;
}

static const Element* get_elm_z(uint8_t z) {
    if(z > 0 && z <= 119) return &DB[z - 1];
    return NULL;
}

#define U(val, unit) (strcmp((val), "N/A") == 0 ? "" : (unit))

typedef struct {
    uint8_t cur_x;
    uint8_t cur_y;
} ViewModel;
typedef struct {
    int scroll;
    char txt[2048];
} DetModel;
typedef struct {
    int scroll;
} AboutModel;

typedef struct {
    Gui* gui;
    ViewDispatcher* disp;
    View* v_splash;
    View* v_grid;
    View* v_exit_splash;
    View* v_details;
    View* v_about;
    TextBox* v_refs;
    TextBox* v_thanks;
    TextBox* v_legend;
    DialogEx* dialog;
    FuriTimer* t_splash;
    FuriTimer* t_exit;
} App;

static void draw_multiline_wrapped(Canvas* canvas, int x, int y, const char* text) {
    int max_chars_per_line = 23;
    int current_y = y;
    const char* ptr = text;
    char buffer[64];
    while(ptr != NULL && *ptr != '\0') {
        const char* next_newline = strchr(ptr, '\n');
        size_t len_to_nl = next_newline ? (size_t)(next_newline - ptr) : strlen(ptr);
        while(len_to_nl > 0) {
            size_t copy_len = len_to_nl > (size_t)max_chars_per_line ? (size_t)max_chars_per_line :
                                                                       len_to_nl;
            if(copy_len == (size_t)max_chars_per_line) {
                while(copy_len > 0 && ptr[copy_len] != ' ' && ptr[copy_len - 1] != ' ') {
                    copy_len--;
                }
                if(copy_len == 0) copy_len = max_chars_per_line;
            }
            memcpy(buffer, ptr, copy_len);
            buffer[copy_len] = '\0';
            if(current_y > -10 && current_y < 70) canvas_draw_str(canvas, x, current_y, buffer);
            current_y += 11;
            ptr += copy_len;
            len_to_nl -= copy_len;
            if(*ptr == ' ') {
                ptr++;
                len_to_nl--;
            }
        }
        if(next_newline)
            ptr = next_newline + 1;
        else
            break;
    }
}

